41/\",\"title\":\"TEXT 41\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/5/\",\"title\":\"Chapter Five\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1547,\"bb\":568080,\"url_path\":\"/en/library/bg/4/42/devanagari/\",\"body_final\":\"तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः ।
छित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत ॥ ४२ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1548,\"bb\":1369,\"url_path\":\"/en/library/bg/4/42/b1369/\",\"body_value\":\"tasmād ajñāna-sambhūtaṁ
hṛt-sthaṁ jñānāsinātmanaḥ
